import {test,expect} from "bun:test";
import Ajv from "ajv";
import stableStringify from "fast-json-stable-stringify";
import "../../../♻️retirement/📋️queue/🧪️tests/🟦️.ts";

type Corpus={cases:{id:string,key:string,keyCapacity:number,value:string,valueCapacity:number}[],grants:number[],expected:{terminalOwners:number,stepBirthBytes:number,reportedReleaseEqualsAllocator:boolean,actualReleaseFitsGrant:boolean,sourcePayloadPointerPreserved:boolean}};
const fixture:Corpus=await Bun.file(new URL("../🧫️fixtures/🔣️.json",import.meta.url)).json();
const schema=await Bun.file(new URL("../🧬️schema/🔣️.json",import.meta.url)).json();
test("ordered retirement grants separate logical work from whole physical release",()=>{
  const ajv=new Ajv({strict:true});ajv.addSchema(schema);const grant=ajv.compile({$ref:schema.$id+"#/$defs/Grant"});const progress=ajv.compile({$ref:schema.$id+"#/$defs/Progress"});
  for(const maximum of fixture.grants){expect(grant({maximumItems:1,maximumCopyBytes:maximum,maximumCapacityBytes:0,maximumReleaseBytes:0,maximumDepth:64})).toBe(true);expect(progress({copiedItems:1,copiedBytes:maximum,retainedCapacityBytes:0,releasedBytes:0,complete:false})).toBe(true);}
  expect(grant({maximumItems:1,maximumBytes:64})).toBe(false);expect(grant({maximumItems:1,maximumCopyBytes:0,maximumCapacityBytes:0,maximumReleaseBytes:-1,maximumDepth:64})).toBe(false);
  expect(fixture.expected).toEqual({terminalOwners:0,stepBirthBytes:0,reportedReleaseEqualsAllocator:true,actualReleaseFitsGrant:true,sourcePayloadPointerPreserved:true});
});
test("ordered retirement payload corpus matches independent unique UTF8 map ownership",()=>{
  for(const row of fixture.cases){const map=new Map([[row.key,row.value]]);const entries=[...map].sort(([a],[b])=>Buffer.compare(Buffer.from(a),Buffer.from(b)));expect(stableStringify(Object.fromEntries(map))).toBe(JSON.stringify(Object.fromEntries(entries)));expect(Buffer.byteLength(row.key)).toBeLessThan(row.keyCapacity);expect(Buffer.byteLength(row.value)).toBeLessThan(row.valueCapacity);expect(map.get(row.key)).toBe(row.value);}
});

import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import Ajv from "ajv";

/** 🧫 Checks portable contribution vectors and neutral registry ownership against Ajv. */
export function runContributionChecks(): number {
  const load = (path: string) => JSON.parse(readFileSync(new URL(path, import.meta.url), "utf8"));
  const fixtures = load("../../🧫️fixtures/📇️contributions/🔣️.json");
  const ajv = new Ajv({ strict: true });
  let checks = 0;
  for (const row of fixtures.cases) {
    let selected: string[] = [...row.selected];
    let accepted = true;
    for (const removed of row.remove) {
      const candidate = selected.filter((owner) => owner !== removed);
      const available = new Set(candidate.map((owner) => `s.stdio.${owner}`));
      const valid = candidate.every((owner) => load(`../../🧫️fixtures/📇️contributions/${owner}.json`).dependencies.every((dependency: string) => available.has(dependency)));
      accepted &&= valid;
      if (valid) selected = candidate;
    }
    assert.equal(accepted, row.accepted);
    assert.deepEqual(selected, row.remaining);
    checks += 2;
  }
  for (const row of fixtures.registrationCases) {
    const left = load(`../../🧫️fixtures/📇️contributions/${row.first}.json`);
    const right = load(`../../🧫️fixtures/📇️contributions/${row.second}.json`);
    const disjoint = (key: string) => left.representations[0][key].every((claim: string) => !right.representations[0][key].includes(claim));
    assert.equal(left.id !== right.id && left.directory !== right.directory && disjoint("mimes") && disjoint("extensions"), row.accepted);
    checks++;
  }
  for (const row of fixtures.receiptCases) {
    assert.equal(row.authoredFactory === false, row.accepted);
    checks++;
  }
  const constraint = ajv.compile(load("../../🧫️fixtures/📇️contributions/🧾️schema-input.json"));
  for (const row of fixtures.validationCases) {
    const source = load("../../🧫️fixtures/📇️contributions/alpha.json");
    source.representations[0].mimes = row.mimes;
    const representation = source.runtime_capabilities.find((item: { category: string }) => item.category === "representation");
    representation.claims = [...row.mimes.map((value: string) => ({ namespace: "mime", value })), ...source.representations[0].extensions.map((value: string) => ({ namespace: "extension", value }))];
    representation.descriptor = `runtime-capability:representation:${representation.claims.map((claim: { namespace: string; value: string }) => `${claim.namespace}:${claim.value}`).join("|")}`;
    assert.equal(row.constraint ? constraint(source) : true, row.accepted);
